<?php require_once __DIR__ . '/includes/config.php';role(['admin','hr','payroll','auditor']);$p=db();if(isset($_GET['csv'])){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename=investigation_report.csv');$o=fopen('php://output','w');fputcsv($o,['Employee No','Name','Period','Amount','Reason','Status']);foreach($p->query('SELECT p.employee_no,e.full_name,p.pay_period,p.gross_amount,i.reason,i.status FROM investigations i JOIN payroll p ON p.id=i.payroll_id LEFT JOIN employees e ON e.id=i.employee_id') as $r)fputcsv($o,$r);exit;}$rows=$p->query('SELECT pay_period,COUNT(*) records,SUM(gross_amount) total FROM payroll GROUP BY pay_period ORDER BY pay_period DESC')->fetchAll();head('Reports');?><h1>Reports</h1><p><a class="button" href="?csv=1">Download investigation CSV</a></p><div class="panel table"><table><tr><th>Pay period</th><th>Records</th><th>Total</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['pay_period'])?></td><td><?=$r['records']?></td><td><?=number_format($r['total'],2)?></td></tr><?php endforeach;?></table></div><?php foot();?>